PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE employees(id TEXT, name TEXT, position TEXT, salary INTEGER, dependents INTEGER);
CREATE TABLE clients(id TEXT, name TEXT, phone TEXT);
CREATE TABLE cases(id TEXT, name TEXT, client TEXT, fee INTEGER, is_deleted INTEGER DEFAULT 0, deleted_at TEXT, deleted_by TEXT, delete_reason TEXT);
CREATE TABLE splits(case_id TEXT, employee_id TEXT, percent INTEGER);
CREATE TABLE payrolls(employee_id TEXT, gross INTEGER, insurance INTEGER, tax INTEGER, net INTEGER);
CREATE TABLE monthly_payrolls(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, month INTEGER, year INTEGER, staff_code TEXT, title TEXT, branch TEXT, working_days INTEGER, dependents INTEGER, gross INTEGER, insurance INTEGER, tax INTEGER, net INTEGER, food_allowance INTEGER DEFAULT 0, gas_allowance INTEGER DEFAULT 0, phone_allowance INTEGER DEFAULT 0, other_benefits INTEGER DEFAULT 0, bonus INTEGER DEFAULT 0, violations INTEGER DEFAULT 0, total_salary INTEGER DEFAULT 0);
CREATE TABLE evaluations(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, month INTEGER, year INTEGER, rating TEXT, bonus_amount INTEGER, notes TEXT, target_type TEXT DEFAULT 'personnel', target_name TEXT);
CREATE TABLE files(id TEXT, case_id TEXT, filename TEXT, path TEXT, is_deleted INTEGER DEFAULT 0, deleted_at TEXT, deleted_by TEXT, delete_reason TEXT);
CREATE TABLE case_text(file_id TEXT, content TEXT);
CREATE TABLE court_schedule(id TEXT, case_id TEXT, date TEXT, location TEXT, note TEXT);
CREATE TABLE tasks(id TEXT, employee_id TEXT, title TEXT, deadline TEXT, status TEXT);
CREATE TABLE invoices(id TEXT, client_id TEXT, case_id TEXT, amount INTEGER, status TEXT, created TEXT);
CREATE TABLE audit_logs(id TEXT PRIMARY KEY, user TEXT, action TEXT, entityType TEXT, entityId TEXT, performedBy TEXT, performedAt TEXT, reason TEXT, result TEXT, time TEXT, details TEXT);
CREATE TABLE services(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, description TEXT, content TEXT, icon TEXT, file_url TEXT, file_name TEXT, category TEXT, is_approved INTEGER DEFAULT 1);
CREATE TABLE legal_services(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, description TEXT, content TEXT, icon TEXT, file_url TEXT, file_name TEXT);
CREATE TABLE team(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, title TEXT, description TEXT, image TEXT, email TEXT, phone TEXT, specialties TEXT, degrees TEXT);
CREATE TABLE recruitment(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, location TEXT, type TEXT, salary TEXT, description TEXT, content TEXT, file_url TEXT, file_name TEXT);
CREATE TABLE recruitment_benefits(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, description TEXT, icon TEXT);
CREATE TABLE recruitment_process(id INTEGER PRIMARY KEY AUTOINCREMENT, step TEXT, title TEXT, description TEXT);
CREATE TABLE news(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, excerpt TEXT, content TEXT, date TEXT, image TEXT, category TEXT, is_approved INTEGER DEFAULT 1, related_service TEXT, video_url TEXT);
CREATE TABLE legal_forms(id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT, category TEXT, description TEXT, content TEXT, is_approved INTEGER DEFAULT 1);
CREATE TABLE judgments(id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT, title TEXT, court TEXT, date TEXT, category TEXT, summary TEXT, content TEXT, is_approved INTEGER DEFAULT 1);
CREATE TABLE precedents(id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT, title TEXT, approved_date TEXT, summary TEXT, law_issue TEXT, solution TEXT, is_approved INTEGER DEFAULT 1);
CREATE TABLE testimonials(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, role TEXT, rating INTEGER, content TEXT, avatar TEXT, company TEXT, is_approved INTEGER DEFAULT 1);
CREATE TABLE land_prices(
    id INTEGER PRIMARY KEY AUTOINCREMENT, 
    province_code TEXT, 
    province_name TEXT, 
    district_id TEXT, 
    district_name TEXT, 
    ward_name TEXT,
    street_name TEXT, 
