    content TEXT,
    doc_type TEXT
  );
CREATE TABLE messages(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, email TEXT, phone TEXT, content TEXT, created_at TEXT, is_read INTEGER DEFAULT 0, reply_notes TEXT, file_url TEXT, file_name TEXT);
CREATE TABLE visitor_stats(id INTEGER PRIMARY KEY AUTOINCREMENT, date TEXT UNIQUE, visitors INTEGER DEFAULT 0, page_views INTEGER DEFAULT 0, chats INTEGER DEFAULT 0);
CREATE TABLE record_types(id INTEGER PRIMARY KEY AUTOINCREMENT, type_code TEXT, type_name TEXT, description TEXT, display_color TEXT, active INTEGER DEFAULT 1);
CREATE TABLE erp_records(id TEXT PRIMARY KEY, data TEXT);
