CREATE TABLE gmail_accounts (email TEXT PRIMARY KEY, pass TEXT, recovery TEXT, proxy TEXT, phone TEXT, status TEXT, created_at TEXT);
CREATE TABLE system_events (
    id TEXT PRIMARY KEY,
