  );
CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT, password TEXT, name TEXT, role TEXT, title TEXT, staff_code TEXT, branch TEXT, start_date TEXT, contract_type TEXT, contract_sign_date TEXT, salary TEXT, bonus TEXT, avatar TEXT, phone TEXT, email TEXT, dob TEXT, gender TEXT, address TEXT, case_id TEXT, manager_id TEXT, practice_areas TEXT, account_type TEXT DEFAULT 'INTERNAL', commission_percent INTEGER DEFAULT 5, bonus_completion_percent INTEGER DEFAULT 10, known_devices TEXT);
