CREATE TABLE iot_devices (
      id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      mac_address TEXT,
      ip_address TEXT,
      location TEXT,
      device_type TEXT NOT NULL, -- 'esp32_cam', 'weather_station', 'rfid_reader', 'led_display'
      status TEXT DEFAULT 'online', -- 'online', 'offline', 'warning'
      last_seen DATETIME DEFAULT CURRENT_TIMESTAMP,
      api_key TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    , model TEXT DEFAULT 'ESP32', firmware TEXT DEFAULT '1.0.0', protocol TEXT DEFAULT 'MQTT', wifi_status TEXT DEFAULT 'connected', mqtt_status TEXT DEFAULT 'connected', rssi INTEGER DEFAULT -65, cpu_usage REAL DEFAULT 15.2, memory_usage REAL DEFAULT 42.1, uptime INTEGER DEFAULT 3600, gpio_schema TEXT);
