INSERT INTO services VALUES(1,'Môi trường & ATTP','Tư vấn pháp lý về môi trường, giấy phép vệ sinh an toàn thực phẩm.',replace('### Dịch vụ Môi trường & ATTP\n\nChúng tôi cung cấp các tư vấn chuyên sâu về pháp luật môi trường và an toàn thực phẩm:\n\n- Tư vấn lập Báo cáo đánh giá tác động môi trường (ĐTM).\n- Hỗ trợ thủ tục xin cấp Giấy phép môi trường.\n- Tư vấn và xin cấp Giấy chứng nhận cơ sở đủ điều kiện an toàn thực phẩm.\n- Đại diện làm việc với cơ quan chức năng khi thanh tra.','\n',char(10)),'Leaf',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(2,'Du lịch & Đầu tư','Tư vấn dự án du lịch, xin giấy phép lữ hành, thủ tục đầu tư nước ngoài.',replace('### Dịch vụ Du lịch & Đầu tư\n\nHỗ trợ nhà đầu tư các thủ tục pháp lý quan trọng:\n\n- Tư vấn thành lập và xin Giấy phép kinh doanh dịch vụ lữ hành.\n- Tư vấn lập dự án đầu tư nước ngoài tại Việt Nam.\n- Hỗ trợ điều chỉnh Giấy chứng nhận đăng ký đầu tư.\n- Tư vấn ưu đãi đầu tư hiện hành.','\n',char(10)),'Globe',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(3,'Bất động sản & Doanh nghiệp','Tư vấn pháp lý dự án bất động sản, M&A, thành lập và quản trị doanh nghiệp.',replace('### Dịch vụ Bất động sản & Doanh nghiệp\n\nGiải pháp pháp lý toàn diện:\n\n- Tư vấn pháp lý dự án bất động sản, thu hồi đất.\n- Tư vấn Mua bán, Sáp nhập doanh nghiệp (M&A).\n- Tư vấn thành lập, giải thể doanh nghiệp.\n- Hỗ trợ quản trị nội bộ và phòng ngừa rủi ro.','\n',char(10)),'Building2',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(4,'Lao động & Kinh doanh','Tư vấn hợp đồng lao động, giải quyết tranh chấp lao động, giấy phép kinh doanh.',replace('### Dịch vụ Lao động & Kinh doanh\n\n- Rà soát hợp đồng lao động, nội quy lao động.\n- Đại diện giải quyết các tranh chấp lao động.\n- Xin cấp Giấy phép lao động cho người nước ngoài.\n- Tư vấn đàm phán tranh chấp hoạt động thương mại.','\n',char(10)),'Briefcase',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(5,'Tranh tụng & Hình sự','Đại diện tham gia tố tụng các vụ án dân sự, hình sự, hành chính.',replace('### Dịch vụ Tranh tụng & Hình sự\n\n- Cử Luật sư tham gia tố tụng bào chữa vụ án hình sự.\n- Bảo vệ quyền lợi hợp pháp trong vụ án Dân sự, Kinh doanh thương mại.\n- Tư vấn thu thập chứng cứ, định hướng giải quyết.\n- Thương lượng, hòa giải trước và trong quá trình tố tụng.','\n',char(10)),'Gavel',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(6,'Sở hữu trí tuệ & Khác','Đăng ký nhãn hiệu, bản quyền tác giả, kiểu dáng công nghiệp.',replace('### Sở hữu trí tuệ & Các dịch vụ khác\n\n- Tư vấn đăng ký Nhãn hiệu, Kiểu dáng, Sáng chế, Bản quyền.\n- Tư vấn xử lý vi phạm quyền Sở hữu trí tuệ.\n- Giải quyết thủ tục thay đổi thông tin hoạt động kinh doanh.\n- Tư vấn pháp luật Hôn nhân gia đình, thừa kế.','\n',char(10)),'Scale',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(7,'Doanh nghiệp','Tư vấn thành lập, mua bán sáp nhập, thay đổi đăng ký kinh doanh và tái cấu trúc doanh nghiệp.',replace('### Tư vấn Pháp luật Doanh nghiệp Toàn diện\n\nChúng tôi đồng hành cùng sự phát triển của doanh nghiệp từ khi khởi sự đến khi vận hành ổn định và phát triển bền vững:\n\n- **Tái cấu trúc & Quản trị**: Tư vấn xây dựng điều lệ, quy chế quản lý nội bộ, phân chia quyền hạn đại diện pháp luật, phòng ngừa tranh chấp nội bộ cổ đông.\n- **Thủ tục đăng ký kinh doanh**: Thay đổi ngành nghề, tăng/giảm vốn điều lệ, chuyển đổi loại hình doanh nghiệp, chuyển nhượng cổ phần/vốn góp.\n- **Thư ký pháp lý thường xuyên**: Giải đáp các vướng mắc phát sinh trong giao dịch hàng ngày, rà soát văn bản hành chính.','\n',char(10)),'Building2',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(8,'Vụ việc dân sự','Bảo vệ quyền lợi trong các tranh chấp đất đai, thừa kế di sản, đòi nợ và bồi thường thiệt hại ngoài hợp đồng.',replace('### Giải quyết Vụ việc Dân sự & Đất đai\n\nHỗ trợ khách hàng bảo vệ quyền và lợi ích hợp pháp tối đa trong các giao dịch và tranh chấp dân sự:\n\n- **Thừa kế & Di chúc**: Tư vấn soạn thảo di chúc hợp pháp, phân chia di sản thừa kế theo pháp luật hoặc di chúc, giải quyết tranh chấp di sản thừa kế phức tạp.\n- **Giao dịch dân sự**: Tư vấn tính pháp lý của hợp đồng đặt cọc, chuyển nhượng, tặng cho, thế chấp tài sản, đòi lại nhà đất cho mượn, cho ở nhờ.\n- **Bồi thường thiệt hại**: Tư vấn và đại diện yêu cầu bồi thường thiệt hại về tính mạng, sức khỏe, danh dự, tài sản do hành vi trái pháp luật gây ra.','\n',char(10)),'Scale',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(9,'Lao động','Tư vấn hợp đồng lao động, nội quy lao động, giải quyết tranh chấp sa thải trái luật.',replace('### Tư vấn Pháp luật Lao động & Nhân sự\n\nKiến tạo môi trường làm việc hài hòa, đúng luật cho doanh nghiệp và bảo vệ quyền lợi hợp pháp cho người lao động:\n\n- **Xây dựng hệ thống quy chế**: Soạn thảo hợp đồng lao động, thỏa ước lao động tập thể, nội quy lao động đăng ký đúng quy định với Sở Lao động.\n- **Giải quyết tranh chấp lao động**: Đại diện đàm phán hoặc tham gia tố tụng trong các vụ án đơn phương chấm dứt hợp đồng lao động, kỷ luật sa thải, bồi thường chi phí đào tạo.\n- **Giấy phép lao động**: Thực hiện thủ tục cấp mới, gia hạn Giấy phép lao động (Work Permit) và Thẻ tạm trú cho người lao động nước ngoài tại Việt Nam.','\n',char(10)),'Briefcase',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(10,'Mua bán & Sáp nhập','Thực hiện rà soát pháp lý (due diligence), đàm phán và soạn thảo hợp đồng M&A.',replace('### Dịch vụ Tư vấn Mua bán & Sáp nhập (M&A)\n\nCung cấp giải pháp chiến lược và kiểm soát rủi ro pháp lý toàn diện cho các giao dịch mua bán, sáp nhập doanh nghiệp:\n\n- **Thẩm định pháp lý (Due Diligence)**: Rà soát toàn bộ hồ sơ đất đai, tài sản, dự án, lao động, thuế và các nghĩa vụ nợ của công ty mục tiêu trước khi chuyển nhượng.\n- **Soạn thảo & Đàm phán hợp đồng**: Thiết kế cấu trúc giao dịch an toàn, soạn thảo hợp đồng mua bán cổ phần (SPA), hợp đồng cổ đông (SHA).\n- **Thủ tục pháp lý hoàn tất**: Thực hiện thủ tục chuyển nhượng, đăng ký cổ đông mới tại cơ quan nhà nước có thẩm quyền.','\n',char(10)),'Building2',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(11,'Hôn nhân và Gia đình','Tư vấn thủ tục ly hôn thuận tình, ly hôn đơn phương, phân chia tài sản chung và giành quyền nuôi con.',replace('### Luật sư Tư vấn Hôn nhân & Gia đình\n\nGiải pháp pháp lý nhân văn, bảo mật thông tin tuyệt đối cho gia đình bạn:\n\n- **Phân chia tài sản**: Tư vấn thỏa thuận tài sản chung/riêng trước khi kết hôn, phân chia tài sản chung của vợ chồng trong thời kỳ hôn nhân hoặc khi ly hôn.\n- **Ly hôn nhanh gọn**: Soạn thảo đơn từ, chuẩn bị hồ sơ ly hôn thuận tình hoặc đơn phương, rút ngắn tối đa thời gian giải quyết tại Tòa án.\n- **Giành quyền nuôi con & Cấp dưỡng**: Luật sư tham gia tố tụng chứng minh điều kiện nuôi con tốt nhất, yêu cầu mức cấp dưỡng hợp lý theo pháp luật.','\n',char(10)),'Heart',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(12,'Tư vấn hợp đồng','Soạn thảo, rà soát và đàm phán các loại hợp đồng kinh tế, thương mại, hợp đồng hợp tác đầu tư.',replace('### Dịch vụ Soạn thảo & Rà soát Hợp đồng Chuyên nghiệp\n\nHợp đồng chặt chẽ là lá chắn pháp lý vững chắc nhất phòng ngừa rủi ro cho cá nhân và doanh nghiệp:\n\n- **Soạn thảo hợp đồng theo yêu cầu**: Hợp đồng mua bán hàng hóa, hợp đồng dịch vụ, hợp đồng hợp tác kinh doanh (BCC), hợp đồng thuê mặt bằng...\n- **Rà soát hợp đồng (Contract Review)**: Phát hiện và cảnh báo các điều khoản mập mờ, bất lợi hoặc vô hiệu theo pháp luật, đề xuất điều khoản thay thế tối ưu.\n- **Hỗ trợ đàm phán**: Tham gia cùng khách hàng đàm phán với đối tác để đạt được các thỏa thuận có lợi nhất về mặt pháp lý và thương mại.','\n',char(10)),'FileText',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(13,'Đầu tư trong & ngoài nước','Hỗ trợ nhà đầu tư nước ngoài xin cấp IRC, thành lập doanh nghiệp FDI và tư vấn đầu tư ra nước ngoài.',replace('### Tư vấn Đầu tư Trong nước & Nước ngoài\n\nCầu nối pháp lý hỗ trợ các nhà đầu tư hiện thực hóa dòng vốn an toàn và hiệu quả:\n\n- **Đầu tư trực tiếp nước ngoài (FDI)**: Xin cấp Giấy chứng nhận đăng ký đầu tư (IRC), đăng ký doanh nghiệp (ERC), thuê đất khu công nghiệp, xin ưu đãi đầu tư.\n- **Đầu tư gián tiếp**: Hỗ trợ nhà đầu tư nước ngoài góp vốn, mua cổ phần của doanh nghiệp Việt Nam theo đúng quy định pháp luật.\n- **Đầu tư ra nước ngoài**: Tư vấn thủ tục chuyển tiền hợp pháp ra nước ngoài, xin giấy chứng nhận đầu tư ra nước ngoài cho doanh nghiệp Việt Nam.','\n',char(10)),'Globe',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(14,'Bất động sản','Thẩm định pháp lý dự án bất động sản, chuyển nhượng quyền sử dụng đất, tách thửa và cấp sổ đỏ.',replace('### Pháp lý Bất động sản & Nhà đất\n\nĐồng hành bảo vệ giá trị tài sản lớn của khách hàng trước các rủi ro pháp lý phức tạp:\n\n- **Thẩm định pháp lý dự án**: Kiểm tra quy hoạch, giấy phép xây dựng, điều kiện bán nhà hình thành trong tương lai của chủ đầu tư trước khi đặt mua.\n- **Chuyển nhượng & Sang tên**: Soạn hồ sơ và thực hiện trọn gói thủ tục sang tên sổ đỏ, sổ hồng, thừa kế, tặng cho quyền sử dụng đất.\n- **Hỗ trợ thủ tục đất đai**: Tách thửa, hợp thửa, chuyển mục đích sử dụng đất (từ đất nông nghiệp lên đất thổ cư), cấp sổ đỏ lần đầu.','\n',char(10)),'Building2',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(15,'Tranh tụng','Luật sư tranh tụng bảo vệ quyền lợi tại Tòa án các cấp và Trọng tài Thương mại quốc tế.',replace('### Luật sư Tranh tụng Chuyên nghiệp tại Tòa án & Trọng tài\n\nĐội ngũ Luật sư tố tụng bản lĩnh, giàu kinh nghiệm thực tế đấu tranh bảo vệ công lý:\n\n- **Thu thập chứng cứ**: Nghiên cứu hồ sơ, phân tích điểm mạnh/yếu, định hướng chiến lược tranh tụng tối ưu nhất cho khách hàng.\n- **Đại diện giải quyết tranh chấp**: Luật sư đại diện tham gia thương lượng, hòa giải giúp các bên đạt được thỏa thuận trước khi phải khởi kiện.\n- **Bảo vệ tại phiên tòa**: Cử Luật sư bào chữa cho bị can/bị cáo trong án Hình sự; bảo vệ quyền lợi cho đương sự trong án Dân sự, Đất đai, Thương mại.','\n',char(10)),'Gavel',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(16,'Hàng hải & Vận chuyển','Tư vấn tranh chấp vận đơn, tổn thất hàng hóa hàng hải, bảo hiểm và bắt giữ tàu biển.',replace('### Tư vấn Pháp luật Hàng hải & Vận tải Quốc tế\n\nHỗ trợ pháp lý chuyên biệt cho các hãng tàu, công ty logistics, bảo hiểm và chủ hàng:\n\n- **Tranh chấp hợp đồng vận chuyển**: Giải quyết tranh chấp liên quan đến vận đơn (B/L), hợp đồng thuê tàu, chậm trễ giao hàng, tổn thất hàng hóa.\n- **Tổn thất & Tai nạn hàng hải**: Tư vấn giải quyết đâm va tàu biển, cứu hộ hàng hải, tổn thất chung (General Average) và bảo hiểm thân tàu.\n- **Bắt giữ tàu biển**: Thực hiện thủ tục yêu cầu Tòa án bắt giữ tàu biển để bảo đảm giải quyết khiếu nại hàng hải hoặc thả tàu bị bắt giữ.','\n',char(10)),'Globe',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(17,'Thuế','Tư vấn lập kế hoạch thuế tối ưu, đại diện giải trình quyết toán thuế và giải quyết khiếu nại thuế.',replace('### Tư vấn Pháp luật Thuế & Tối ưu Chi phí Thuế\n\nGiúp doanh nghiệp chủ động kiểm soát rủi ro về thuế và thực hiện nghĩa vụ tài chính hiệu quả nhất:\n\n- **Hoạch định kế hoạch thuế**: Tư vấn áp dụng ưu đãi thuế TNDN, thuế suất GTGT cho các dự án mới, tối ưu cơ cấu chi phí hợp lý được trừ.\n- **Hỗ trợ thanh tra thuế**: Rà soát trước sổ sách kế toán, phát hiện rủi ro, cùng doanh nghiệp giải trình số liệu trực tiếp với cơ quan thuế.\n- **Khiếu nại về thuế**: Đại diện thực hiện thủ tục khiếu nại các quyết định truy thu thuế, xử phạt hành chính về thuế không đúng quy định pháp luật.','\n',char(10)),'Shield',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(18,'Di trú & Visa','Tư vấn thủ tục làm thẻ tạm trú, giấy phép lao động, visa định cư kết hôn nước ngoài.',replace('### Dịch vụ Di trú, Visa & Thẻ tạm trú\n\nHỗ trợ thủ tục xuất nhập cảnh cho công dân nước ngoài và công dân Việt Nam nhanh chóng, đúng quy định:\n\n- **Visa & Thẻ tạm trú (TRC)**: Xin cấp thẻ tạm trú thời hạn từ 2 đến 5 năm cho nhà đầu tư nước ngoài, chuyên gia nước ngoài làm việc tại Việt Nam.\n- **Hợp pháp hóa lãnh sự**: Thực hiện thủ tục dịch thuật công chứng, hợp pháp hóa lãnh sự các giấy tờ nước ngoài để sử dụng tại Việt Nam.\n- **Di trú định cư**: Tư vấn hồ sơ bảo lãnh định cư, visa kết hôn, visa du học các nước Châu Âu, Mỹ, Úc, Nhật Bản.','\n',char(10)),'Globe',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO services VALUES(19,'Hộ tịch','Thủ tục làm giấy khai sinh quá hạn, khai sinh có yếu tố nước ngoài, nhận cha mẹ con.',replace('### Tư vấn Thủ tục Hộ tịch & Nhân thân\n\nĐảm bảo đầy đủ các quyền nhân thân cơ bản cho công dân một cách nhanh gọn và chuẩn xác:\n\n- **Khai sinh có yếu tố nước ngoài**: Hỗ trợ đăng ký khai sinh cho con có cha hoặc mẹ là người nước ngoài, trẻ em sinh ra tại nước ngoài về cư trú.\n- **Xác định quan hệ nhân thân**: Thực hiện thủ tục nhận cha, mẹ, con, đăng ký khai sinh muộn, thay đổi họ tên, cải chính hộ tịch trên giấy tờ gốc.\n- **Đăng ký kết hôn**: Tư vấn thủ tục kết hôn giữa người Việt Nam và người nước ngoài, đảm bảo tính hợp pháp của các giấy tờ cần thiết.','\n',char(10)),'Heart',NULL,NULL,'Lĩnh vực hoạt động',1);
INSERT INTO legal_services VALUES(1,'Tư vấn pháp luật thường xuyên','Cung cấp dịch vụ tư vấn pháp lý định kỳ cho doanh nghiệp.',replace('### Tư vấn pháp luật thường xuyên\n\nĐóng vai trò như một bộ phận pháp chế thuê ngoài:\n\n- Rà soát tính hợp pháp của các quyết định nội bộ.\n- Đánh giá rủi ro pháp lý trong hợp đồng.\n- Cập nhật quy định pháp luật mới.\n- Tư vấn vấn đề pháp lý phát sinh hàng ngày.','\n',char(10)),'Shield',NULL,NULL);
INSERT INTO legal_services VALUES(2,'Tư vấn dự án đầu tư','Hỗ trợ pháp lý toàn diện cho các dự án đầu tư trong và ngoài nước.',replace('### Tư vấn dự án đầu tư\n\nGiải pháp pháp lý toàn diện:\n\n- Đánh giá khả năng và điều kiện pháp lý của dự án.\n- Lựa chọn hình thức đầu tư phù hợp.\n- Soạn thảo hợp đồng hợp tác.\n- Thực hiện thủ tục Giấy chứng nhận đầu tư.','\n',char(10)),'Briefcase',NULL,NULL);
INSERT INTO legal_services VALUES(3,'Giải quyết tranh chấp','Đại diện khách hàng giải quyết các tranh chấp thương mại, dân sự.',replace('### Giải quyết tranh chấp\n\nBảo vệ quyền lợi tối đa:\n\n- Tranh chấp hợp đồng mua bán.\n- Tranh chấp giữa thành viên/cổ đông.\n- Tranh chấp sở hữu trí tuệ, bất động sản.\n- Đại diện thương lượng, hoà giải hoặc tham gia Tòa án/Trọng tài.','\n',char(10)),'Gavel',NULL,NULL);
INSERT INTO legal_services VALUES(4,'Đại diện ngoài tố tụng','Đại diện khách hàng làm việc với cơ quan nhà nước, đối tác.',replace('### Đại diện ngoài tố tụng\n\n- Đại diện khách hàng tham gia họp, đàm phán.\n- Đại diện làm việc với cơ quan chức năng, thuế.\n- Thực hiện thủ tục khiếu nại, tố cáo.\n- Thực hiện thủ tục thi hành án dân sự.','\n',char(10)),'Users',NULL,NULL);
INSERT INTO legal_services VALUES(5,'Dịch vụ giấy phép','Thực hiện các thủ tục xin cấp các loại giấy phép con.',replace('### Dịch vụ giấy phép\n\nXin cấp các loại giấy tờ, giấy phép:\n\n- Giấy phép kinh doanh dịch vụ lữ hành, vận tải.\n- Giấy phép thành lập cơ sở giáo dục.\n- Giấy phép vệ sinh an toàn thực phẩm.\n- Giấy phép phòng cháy chữa cháy.','\n',char(10)),'FileText',NULL,NULL);
INSERT INTO legal_services VALUES(6,'Tư vấn hợp đồng','Soạn thảo, rà soát và tư vấn đàm phán các loại hợp đồng.',replace('### Tư vấn hợp đồng\n\nKiểm soát rủi ro và tối đa hóa lợi ích:\n\n- Đàm phán, xây dựng dự thảo hợp đồng.\n- Rà soát, chỉ ra điểm bất lợi và đề xuất sửa đổi.\n- Tư vấn thủ tục và điều kiện đảm bảo hiệu lực.\n- Giải quyết tranh chấp quá trình thực hiện hợp đồng.','\n',char(10)),'FileText',NULL,NULL);
INSERT INTO legal_services VALUES(7,'Dịch vụ luật sư','Tư vấn pháp lý thường xuyên, giải quyết tranh chấp dân sự, thương mại và hình sự.',replace('### Dịch vụ Luật sư Chuyên nghiệp & Uy tín\n\nChúng tôi cung cấp đội ngũ Luật sư giàu kinh nghiệm thực tế, sẵn sàng hỗ trợ khách hàng giải quyết mọi vướng mắc pháp lý:\n\n- **Tư vấn pháp lý thường xuyên**: Đồng hành cùng cá nhân và doanh nghiệp trong hoạt động hàng ngày.\n- **Tham gia tố tụng**: Bào chữa trong các vụ án Hình sự; Bảo vệ quyền và lợi ích hợp pháp trong các vụ án Dân sự, Đất đai, Hôn nhân gia đình, Kinh doanh thương mại, Lao động...\n- **Đại diện ngoài tố tụng**: Thực hiện đàm phán, thương lượng, làm việc với các đối tác và cơ quan Nhà nước có thẩm quyền.\n- **Soạn thảo văn bản**: Đơn khởi kiện, đơn khiếu nại, các loại hợp đồng và văn bản pháp lý khác.','\n',char(10)),'Gavel',NULL,NULL);
INSERT INTO legal_services VALUES(8,'Thành lập công ty','Trọn gói thủ tục đăng ký kinh doanh, chuẩn bị hồ sơ thành lập doanh nghiệp, khắc dấu và khai thuế ban đầu.',replace('### Dịch vụ Thành lập Công ty Trọn gói\n\nGiải pháp tối ưu cho người khởi nghiệp, cam kết nhanh chóng, uy tín và không phát sinh chi phí:\n\n- **Tư vấn trước thành lập**: Lựa chọn loại hình doanh nghiệp phù hợp (TNHH, Cổ phần, Doanh nghiệp tư nhân...), đặt tên công ty, chọn ngành nghề kinh doanh, vốn điều lệ và địa chỉ trụ sở.\n- **Soạn thảo hồ sơ**: Hoàn thiện toàn bộ hồ sơ đăng ký doanh nghiệp theo quy định.\n- **Nộp hồ sơ & Nhận kết quả**: Đại diện khách hàng nộp hồ sơ tại Sở Kế hoạch và Đầu tư, nhận Giấy chứng nhận đăng ký doanh nghiệp.\n- **Thủ tục sau thành lập**: Khắc dấu tròn công ty, công bố mẫu dấu, đăng ký tài khoản ngân hàng, mua chữ ký số, hóa đơn điện tử, kê khai thuế ban đầu.','\n',char(10)),'Building2',NULL,NULL);
INSERT INTO legal_services VALUES(9,'Giấy phép kinh doanh','Xin cấp các loại giấy phép con, giấy phép hoạt động ngành nghề có điều kiện.',replace('### Xin cấp Giấy phép kinh doanh & Giấy phép con\n\nHỗ trợ doanh nghiệp hoàn thiện các điều kiện pháp lý để hoạt động trong các ngành nghề kinh doanh có điều kiện:\n\n- **Giấy phép lữ hành**: Lữ hành nội địa, lữ hành quốc tế.\n- **Giấy phép giáo dục**: Thành lập trung tâm ngoại ngữ, trung tâm tin học, tư vấn du học.\n- **Giấy phép vận tải**: Phù hiệu xe, giấy phép kinh doanh vận tải bằng xe ô tô.\n- **Giấy phép hoạt động khác**: Giấy phép bán lẻ rượu, thuốc lá, giấy phép phòng cháy chữa cháy, cam kết môi trường.','\n',char(10)),'FileText',NULL,NULL);
INSERT INTO legal_services VALUES(10,'Đăng ký hộ kinh doanh','Hỗ trợ đăng ký thành lập hộ kinh doanh cá thể tại các quận, huyện nhanh chóng, thủ tục đơn giản.',replace('### Đăng ký thành lập Hộ kinh doanh cá thể\n\nPhương án kinh doanh phù hợp cho quy mô nhỏ, gia đình, thủ tục tinh gọn và tiết kiệm thuế:\n\n- **Tư vấn đặt tên**: Đảm bảo tên hộ kinh doanh không trùng lặp và tuân thủ pháp luật.\n- **Tư vấn ngành nghề**: Lựa chọn ngành nghề kinh doanh phù hợp với năng lực hoạt động.\n- **Soạn hồ sơ**: Chuẩn bị đơn đăng ký, bản sao giấy tờ cá nhân và các tài liệu liên quan khác.\n- **Đại diện nộp hồ sơ**: Nộp hồ sơ tại UBND quận/huyện và bàn giao Giấy đăng ký hộ kinh doanh cùng mã số thuế tận nơi.','\n',char(10)),'Users',NULL,NULL);
INSERT INTO legal_services VALUES(27,'Đăng ký mã số thuế','Cấp mới mã số thuế cá nhân, doanh nghiệp và hướng dẫn sử dụng hóa đơn điện tử.',replace('### Dịch vụ Đăng ký mã số thuế cá nhân & doanh nghiệp\n\nĐảm bảo nghĩa vụ thuế được thực hiện đúng hạn, chính xác và chuyên nghiệp:\n\n- **Mã số thuế cá nhân**: Đăng ký mã số thuế cho người lao động, người có thu nhập chịu thuế.\n- **Mã số thuế doanh nghiệp**: Cấp mã số thuế tích hợp trên Giấy chứng nhận đăng ký kinh doanh.\n- **Mã số thuế phụ thuộc**: Đăng ký mã số thuế cho người phụ thuộc để giảm trừ gia cảnh.\n- **Khai thuế ban đầu**: Thiết lập hồ sơ thuế ban đầu cho doanh nghiệp mới thành lập.','\n',char(10)),'Shield',NULL,NULL);
INSERT INTO legal_services VALUES(28,'Quyết toán thuế','Thực hiện quyết toán thuế thu nhập cá nhân, thuế thu nhập doanh nghiệp định kỳ hoặc khi giải thể.',replace('### Dịch vụ Quyết toán thuế Chuyên nghiệp\n\nHỗ trợ doanh nghiệp và cá nhân rà soát, nộp hồ sơ quyết toán thuế đúng quy định pháp luật:\n\n- **Quyết toán thuế TNCN**: Dành cho cá nhân có nhiều nguồn thu nhập, người nước ngoài tại Việt Nam hoặc ủy quyền qua tổ chức chi trả.\n- **Quyết toán thuế TNDN**: Lập báo cáo quyết toán thuế thu nhập doanh nghiệp hàng năm, tối ưu chi phí hợp lý.\n- **Hỗ trợ thanh tra thuế**: Chuẩn bị hồ sơ sổ sách, đại diện giải trình số liệu với cơ quan thuế khi có thanh tra, kiểm tra.','\n',char(10)),'FileText',NULL,NULL);
INSERT INTO legal_services VALUES(29,'Dịch vụ làm visa','Tư vấn thủ tục và làm visa nhập cảnh, xuất cảnh, gia hạn visa, thẻ tạm trú cho người nước ngoài.',replace('### Dịch vụ Visa & Thẻ tạm trú\n\nHỗ trợ thủ tục xuất nhập cảnh cho người Việt Nam ra nước ngoài và người nước ngoài vào Việt Nam:\n\n- **Visa du lịch, công tác**: Tư vấn xin visa các nước Châu Âu, Mỹ, Úc, Nhật Bản, Hàn Quốc...\n- **Công văn nhập cảnh**: Xin công văn cho người nước ngoài vào Việt Nam làm việc, du lịch.\n- **Gia hạn Visa**: Thực hiện gia hạn thời gian tạm trú hợp pháp tại Việt Nam.\n- **Thẻ tạm trú & Giấy phép lao động**: Làm thẻ tạm trú (2-5 năm), Giấy phép lao động cho chuyên gia, lao động kỹ thuật nước ngoài.','\n',char(10)),'Globe',NULL,NULL);
INSERT INTO legal_services VALUES(30,'Dịch vụ ly hôn','Tư vấn ly hôn thuận tình, đơn phương, phân chia tài sản và giành quyền nuôi con nhanh chóng, bảo mật.',replace('### Dịch vụ Luật sư Giải quyết Ly hôn nhanh, bảo mật\n\nĐóng hành và bảo vệ tối đa quyền lợi hợp pháp của bạn trong giai đoạn khó khăn:\n\n- **Ly hôn thuận tình**: Tư vấn soạn hồ sơ, nộp đơn và hỗ trợ giải quyết nhanh gọn tại Tòa án trong vòng 7 - 15 ngày, hạn chế số lần lên Tòa.\n- **Ly hôn đơn phương**: Luật sư hỗ trợ thu thập chứng cứ chứng minh mâu thuẫn trầm trọng, bảo vệ quyền lợi khi tranh chấp quyền nuôi con và phân chia tài sản chung.\n- **Ly hôn có yếu tố nước ngoài**: Giải quyết thủ tục ly hôn khi một bên ở nước ngoài hoặc là người nước ngoài.','\n',char(10)),'Heart',NULL,NULL);
INSERT INTO legal_services VALUES(31,'Tạm ngừng kinh doanh','Hỗ trợ làm thủ tục tạm ngừng hoạt động kinh doanh cho doanh nghiệp theo quy định mới nhất.',replace('### Thủ tục Tạm ngừng hoạt động kinh doanh\n\nHỗ trợ doanh nghiệp tạm dừng hoạt động hợp pháp để tái cấu trúc hoặc giải quyết khó khăn tài chính:\n\n- **Tư vấn thời hạn**: Giải thích quy định về thời gian tạm ngừng tối đa, quyền và nghĩa vụ thuế trong thời gian tạm ngừng.\n- **Soạn hồ sơ**: Chuẩn bị thông báo tạm ngừng, nghị quyết/quyết định của Hội đồng thành viên/Hội đồng quản trị.\n- **Nộp hồ sơ**: Đại diện nộp hồ sơ lên Phòng Đăng ký kinh doanh và nhận thông báo chấp thuận tạm ngừng.','\n',char(10)),'Briefcase',NULL,NULL);
INSERT INTO legal_services VALUES(32,'Kiểm nghiệm sản phẩm','Hỗ trợ lấy mẫu, gửi kiểm nghiệm và nhận kết quả kiểm nghiệm sản phẩm tại các trung tâm uy tín.',replace('### Dịch vụ Kiểm nghiệm sản phẩm chuyên nghiệp\n\nKiểm nghiệm chất lượng sản phẩm là bước bắt buộc để thực hiện công bố chất lượng sản phẩm ra thị trường:\n\n- **Tư vấn chỉ tiêu**: Lên chỉ tiêu kiểm nghiệm phù hợp cho từng loại sản phẩm (thực phẩm, mỹ phẩm, thức ăn chăn nuôi, hàng tiêu dùng) để tiết kiệm chi phí mà vẫn đúng luật.\n- **Gửi mẫu**: Đại diện gửi mẫu đến các trung tâm kiểm nghiệm được Nhà nước chỉ định (Eurofins, Quatest...).\n- **Nhận kết quả**: Theo dõi quá trình, nhận phiếu kết quả kiểm nghiệm đạt chuẩn.','\n',char(10)),'Leaf',NULL,NULL);
INSERT INTO legal_services VALUES(33,'Lý lịch tư pháp','Xin cấp phiếu Lý lịch tư pháp số 1, số 2 cho công dân Việt Nam và người nước ngoài nhanh gọn.',replace('### Dịch vụ Làm Lý lịch tư pháp nhanh toàn quốc\n\nHỗ trợ khách hàng xin phiếu Lý lịch tư pháp số 1 và số 2 nhanh chóng, không cần xếp hàng chờ đợi:\n\n- **Lý lịch tư pháp số 1**: Phục vụ nhu cầu xin việc làm, đi học, làm thủ tục hành chính...\n- **Lý lịch tư pháp số 2**: Phục vụ mục đích đi định cư, kết hôn với người nước ngoài, làm visa định cư...\n- **Đặc biệt**: Hỗ trợ làm nhanh cho người đang ở nước ngoài, người ngoại tỉnh, người nước ngoài từng cư trú tại Việt Nam.','\n',char(10)),'Shield',NULL,NULL);
INSERT INTO legal_services VALUES(34,'Báo cáo tài chính','Lập báo cáo tài chính cuối năm, rà soát sổ sách kế toán, báo cáo thuế cho doanh nghiệp.',replace('### Dịch vụ Lập Báo cáo tài chính cuối năm\n\nĐảm bảo hệ thống sổ sách kế toán minh bạch, chính xác và tuân thủ đúng chuẩn mực kế toán Việt Nam:\n\n- **Thu thập dữ liệu**: Rà soát chứng từ đầu vào, đầu ra, tờ khai thuế đã nộp.\n- **Xử lý số liệu**: Định khoản kế toán, lập bảng cân đối phát sinh, báo cáo kết quả hoạt động kinh doanh, lưu chuyển tiền tệ, thuyết minh báo cáo tài chính.\n- **Nộp báo cáo**: Nộp báo cáo tài chính đến cơ quan thuế, cơ quan thống kê đúng thời hạn pháp luật.','\n',char(10)),'FileText',NULL,NULL);
INSERT INTO legal_services VALUES(35,'Hoàn thuế thu nhập cá nhân','Hỗ trợ hồ sơ xin hoàn thuế thu nhập cá nhân cho người lao động, chuyên gia nước ngoài.',replace('### Dịch vụ Hoàn thuế thu nhập cá nhân (TNCN)\n\nHỗ trợ người lao động lấy lại số tiền thuế TNCN đã nộp thừa một cách nhanh chóng, đúng luật:\n\n- **Rà soát chứng từ**: Kiểm tra chứng từ khấu trừ thuế, thư xác nhận thu nhập, hồ sơ người phụ thuộc.\n- **Tính toán số thuế hoàn**: Tính chính xác số thuế được hoàn hoặc số thuế nộp thêm.\n- **Nộp hồ sơ quyết toán**: Đại diện nộp hồ sơ lên cơ quan thuế quản lý và theo dõi nhận tiền hoàn thuế về tài khoản cá nhân.','\n',char(10)),'Scale',NULL,NULL);
INSERT INTO legal_services VALUES(36,'Đăng ký kinh doanh','Thay đổi nội dung đăng ký doanh nghiệp như tăng vốn, thay đổi đại diện pháp luật, chuyển địa chỉ.',replace('### Thay đổi nội dung Đăng ký kinh doanh\n\nHỗ trợ doanh nghiệp cập nhật các thay đổi trong quá trình hoạt động kinh doanh theo quy định mới:\n\n- **Tăng/Giảm vốn điều lệ**: Thay đổi cơ cấu góp vốn của các thành viên, cổ đông.\n- **Thay đổi đại diện pháp luật**: Thay đổi Giám đốc, Chủ tịch công ty.\n- **Thay đổi trụ sở, tên công ty**: Chuyển địa chỉ cùng quận hoặc khác quận, tỉnh thành.\n- **Thay đổi ngành nghề**: Thêm mới hoặc lược bỏ các ngành nghề kinh doanh.','\n',char(10)),'Building2',NULL,NULL);
INSERT INTO legal_services VALUES(37,'Công bố sản phẩm','Thực hiện thủ tục tự công bố, công bố chất lượng sản phẩm thực phẩm, mỹ phẩm nhập khẩu và trong nước.',replace('### Dịch vụ Tự công bố & Công bố chất lượng sản phẩm\n\nĐảm bảo sản phẩm của doanh nghiệp đủ điều kiện lưu hành hợp pháp trên thị trường Việt Nam:\n\n- **Thực phẩm thường & Nhập khẩu**: Soạn hồ sơ tự công bố sản phẩm, nộp lên cơ quan quản lý an toàn thực phẩm.\n- **Thực phẩm chức năng, bảo vệ sức khỏe**: Đăng ký công bố sản phẩm tại Cục An toàn thực phẩm - Bộ Y tế.\n- **Mỹ phẩm**: Công bố mỹ phẩm sản xuất trong nước và mỹ phẩm nhập khẩu.','\n',char(10)),'Leaf',NULL,NULL);
INSERT INTO legal_services VALUES(38,'Báo cáo thuế','Dịch vụ kế toán thuế trọn gói hàng tháng, hàng quý, nộp tờ khai thuế đúng hạn, chính xác.',replace('### Dịch vụ Kế toán & Báo cáo thuế trọn gói\n\nGiải pháp tiết kiệm chi phí tối đa cho doanh nghiệp vừa và nhỏ, không cần thuê kế toán nội bộ:\n\n- **Kê khai thuế hàng tháng/quý**: Lập và nộp tờ khai thuế GTGT, thuế TNCN, tình hình sử dụng hóa đơn.\n- **Cân đối chi phí**: Tư vấn hóa đơn hợp lệ, hợp pháp, cân đối doanh thu - chi phí tối ưu nhất cho doanh nghiệp.\n- **Sổ sách kế toán**: Thiết lập hệ thống sổ sách kế toán theo quy chuẩn, in và lưu trữ hồ sơ cẩn thận.','\n',char(10)),'FileText',NULL,NULL);
INSERT INTO legal_services VALUES(39,'Giấy chứng nhận vệ sinh an toàn thực phẩm','Tư vấn set up cơ sở và xin cấp giấy chứng nhận đủ điều kiện an toàn thực phẩm cho nhà hàng, hộ kinh doanh.',replace('### Xin Giấy phép Vệ sinh an toàn thực phẩm (ATTP)\n\nĐảm bảo nhà hàng, quán ăn, cơ sở sản xuất thực phẩm hoạt động đúng luật, tránh bị phạt nặng:\n\n- **Khảo sát thực tế**: Khảo sát mặt bằng, tư vấn cách bố trí bếp theo nguyên tắc một chiều.\n- **Tập huấn & Khám sức khỏe**: Hỗ trợ thủ tục đăng ký tập huấn kiến thức ATTP và khám sức khỏe cho chủ cơ sở và nhân viên.\n- **Soạn & Nộp hồ sơ**: Chuẩn bị hồ sơ xin cấp giấy chứng nhận đủ điều kiện gửi cơ quan chức năng.\n- **Đón đoàn thẩm định**: Hướng dẫn cơ sở chuẩn bị sổ sách, mẫu lưu thực phẩm để đón đoàn thẩm định đạt kết quả tốt nhất.','\n',char(10)),'Leaf',NULL,NULL);
INSERT INTO legal_services VALUES(40,'Giải thể công ty','Thực hiện thủ tục đóng mã số thuế, quyết toán thuế giải thể, trả con dấu và hoàn tất giải thể doanh nghiệp.',replace('### Dịch vụ Giải thể Doanh nghiệp trọn gói\n\nHỗ trợ doanh nghiệp hoàn tất thủ tục chấm dứt hoạt động một cách an toàn, đúng pháp luật, tránh nợ đọng thuế:\n\n- **Quyết toán thuế giải thể**: Đây là bước khó khăn nhất, chúng tôi sẽ hỗ trợ dọn dẹp sổ sách kế toán, nộp hồ sơ quyết toán thuế giải thể với cơ quan thuế.\n- **Đóng mã số thuế**: Nhận thông báo khóa mã số thuế từ cơ quan thuế quản lý.\n- **Giải thể tại Sở KH&ĐT**: Nộp hồ sơ xin giải thể doanh nghiệp tại Phòng Đăng ký kinh doanh và nhận quyết định giải thể chính thức.','\n',char(10)),'Building2',NULL,NULL);
INSERT INTO legal_services VALUES(41,'Đầu tư nước ngoài','Tư vấn thành lập công ty có vốn nước ngoài (FDI), điều chỉnh giấy chứng nhận đầu tư, xin visa đầu tư.',replace('### Tư vấn Đầu tư nước ngoài tại Việt Nam\n\nHỗ trợ toàn diện cho nhà đầu tư nước ngoài thiết lập và vận hành doanh nghiệp FDI tại Việt Nam:\n\n- **Thành lập công ty FDI**: Xin cấp Giấy chứng nhận đăng ký đầu tư (IRC) và Giấy chứng nhận đăng ký doanh nghiệp (ERC).\n- **Góp vốn, mua cổ phần**: Tư vấn và thực hiện thủ tục cho nhà đầu tư nước ngoài mua lại phần vốn góp của công ty Việt Nam.\n- **Thay đổi dự án đầu tư**: Hỗ trợ điều chỉnh quy mô, tăng vốn, thay đổi địa điểm dự án đầu tư.','\n',char(10)),'Globe',NULL,NULL);
INSERT INTO legal_services VALUES(42,'Làm giấy khai sinh','Tư vấn thủ tục đăng ký khai sinh quá hạn, khai sinh có yếu tố nước ngoài, đăng ký nhận cha mẹ con.',replace('### Tư vấn thủ tục Đăng ký khai sinh & Nhận cha mẹ con\n\nHỗ trợ pháp lý tận tâm để đảm bảo quyền nhân thân cho trẻ em:\n\n- **Đăng ký khai sinh có yếu tố nước ngoài**: Khi cha hoặc mẹ là người nước ngoài, trẻ em sinh ra tại Việt Nam hoặc nước ngoài.\n- **Khai sinh quá hạn**: Tư vấn thủ tục, giấy tờ thay thế khi đăng ký khai sinh muộn.\n- **Nhận cha, mẹ, con**: Thực hiện thủ tục nhận con ngoài giá thú, xét nghiệm ADN chứng minh quan hệ huyết thống để làm giấy khai sinh hợp lệ.','\n',char(10)),'Heart',NULL,NULL);
INSERT INTO team VALUES(1,'Luật sư Nguyễn Văn A','Giám đốc',NULL,'https://picsum.photos/seed/lawyer1/400/500',NULL,NULL,NULL,NULL);
INSERT INTO team VALUES(2,'Luật sư Trần Thị B','Trưởng phòng',NULL,'https://picsum.photos/seed/lawyer2/400/500',NULL,NULL,NULL,NULL);
INSERT INTO team VALUES(3,'Luật sư Lê Văn C','Chuyên viên pháp lý',NULL,'https://picsum.photos/seed/lawyer3/400/500',NULL,NULL,NULL,NULL);
INSERT INTO recruitment VALUES(1,'Luật sư Tranh tụng & Giải quyết tranh chấp','Hà Nội','Toàn thời gian','Thỏa thuận (Cạnh tranh)','Chịu trách nhiệm đại diện khách hàng tham gia tranh tụng tại Tòa án các cấp và các cơ quan tố tụng. Nghiên cứu hồ sơ, tư vấn phương án giải quyết tối ưu.',replace('### Chi tiết công việc:\n- Nghiên cứu hồ sơ vụ việc, thu thập tài liệu chứng cứ cần thiết để phục vụ công tác tranh tụng.\n- Soạn thảo các văn bản pháp lý chuyên sâu: Đơn khởi kiện, Bản tự khai, Ý kiến pháp lý, Bài bào chữa, Bản luận cứ bảo vệ quyền lợi hợp pháp...\n- Đại diện theo ủy quyền hoặc cử người bảo vệ quyền và lợi ích hợp pháp cho khách hàng tại Tòa án nhân dân, Trung tâm Trọng tài và các Cơ quan nhà nước có thẩm quyền.\n- Tư vấn, định hướng giải pháp phòng ngừa rủi ro tranh chấp hợp đồng, lao động, đất đai cho doanh nghiệp.\n\n### Yêu cầu ứng viên:\n- Đã được cấp Thẻ hành nghề Luật sư tại Việt Nam.\n- Tối thiểu 03 - 05 năm kinh nghiệm tham gia tranh tụng thực tế (ưu tiên lĩnh vực Dân sự, Kinh doanh thương mại, Đất đai).\n- Tư duy logic pháp lý nhạy bén, bản lĩnh nghề nghiệp vững vàng, chịu được áp lực công việc cao.\n- Khả năng tranh luận, thuyết trình tốt và thuyết phục trước hội đồng xét xử.\n\n### Quyền lợi & Chế độ đãi ngộ:\n- Lương cứng hấp dẫn (trao đổi trực tiếp theo năng lực) + Thưởng vụ việc vượt trội (lên đến 15 - 20% giá trị hợp đồng dịch vụ).\n- Tham gia đầy đủ các chế độ BHXH, BHYT, BHTN theo quy định pháp luật.\n- Được hỗ trợ chi phí công tác, văn phòng phẩm và các công cụ phục vụ công việc.\n- Du lịch nghỉ dưỡng 5 sao thường niên cùng công ty. Lộ trình phát triển lên vị trí Luật sư thành viên sáng lập.','\n',char(10)),NULL,NULL);
INSERT INTO recruitment VALUES(2,'Chuyên viên Tư vấn Pháp lý Doanh nghiệp','TP. Hồ Chí Minh','Toàn thời gian','15 - 25 triệu VNĐ','Thực hiện dịch vụ tư vấn thành lập, mua bán sáp nhập (M&A), thay đổi đăng ký kinh doanh và rà soát hợp đồng thương mại cho các khách hàng doanh nghiệp lớn.',replace('### Chi tiết công việc:\n- Thực hiện tư vấn và trực tiếp triển khai thủ tục: Thành lập doanh nghiệp, thay đổi đăng ký kinh doanh, xin các loại Giấy phép con (vệ sinh an toàn thực phẩm, lữ hành, phòng cháy chữa cháy...).\n- Tư vấn thường xuyên cho các doanh nghiệp: Rà soát hợp đồng thương mại, tư vấn pháp luật lao động, sở hữu trí tuệ, quản trị nội bộ doanh nghiệp.\n- Hỗ trợ Luật sư trong các giao dịch M&A (mua bán & sáp nhập), soạn thảo báo cáo rà soát đặc biệt (Due Diligence).\n- Nghiên cứu cập nhật các văn bản quy phạm pháp luật mới để chia sẻ với đội ngũ và xây dựng bản tin pháp luật gửi khách hàng.\n\n### Yêu cầu ứng viên:\n- Tốt nghiệp cử nhân Đại học chuyên ngành Luật trở lên (Ưu tiên ĐH Luật Hà Nội, ĐH Luật TP.HCM, ĐH Quốc Gia).\n- Tối thiểu 02 năm kinh nghiệm làm việc tại tổ chức hành nghề luật hoặc phòng pháp chế doanh nghiệp lớn.\n- Am hiểu sâu sắc Luật Doanh nghiệp, Luật Đầu tư, Luật Thương mại và các quy trình hành chính công.\n- Sử dụng tiếng Anh tốt (đặc biệt là đọc hiểu, soạn thảo hợp đồng thương mại) là một lợi thế lớn.\n\n### Quyền lợi & Chế độ đãi ngộ:\n- Thu nhập cạnh tranh: Lương cứng từ 15 - 25 triệu VNĐ (tùy năng lực) + hoa hồng tư vấn hấp dẫn (5% - 10% doanh thu mang về).\n- Thưởng hiệu quả công việc hàng tháng/quý theo KPI rõ ràng.\n- Được đào tạo định kỳ bởi các Luật sư thành viên, định hướng thi chứng chỉ hành nghề Luật sư.\n- Môi trường làm việc trẻ trung, năng động, tiện nghi hiện đại tại trung tâm quận 1.','\n',char(10)),NULL,NULL);
INSERT INTO recruitment VALUES(3,'Thực tập sinh Pháp lý (Legal Intern)','TP. Hồ Chí Minh','Thực tập','Hỗ trợ xăng xe + Thưởng hiệu quả','Cơ hội rèn luyện thực tế dành cho các bạn sinh viên năm cuối ngành Luật. Hỗ trợ Luật sư nghiên cứu hồ sơ, thực hiện các thủ tục hành chính công.',replace('### Chi tiết công việc:\n- Hỗ trợ Luật sư và Chuyên viên pháp lý nghiên cứu văn bản pháp luật, tra cứu thông tin phục vụ vụ việc thực tế.\n- Đi nộp hồ sơ, tiếp nhận kết quả tại các Cơ quan nhà nước dưới sự hướng dẫn của Chuyên viên pháp lý.\n- Soạn thảo sơ bộ các văn bản hành chính, chuẩn bị hồ sơ thành lập doanh nghiệp, giấy phép con đơn giản.\n- Tham gia dịch thuật tài liệu pháp lý (nếu có năng lực ngoại ngữ) và hỗ trợ công tác lưu trữ hồ sơ văn phòng.\n\n### Yêu cầu ứng viên:\n- Sinh viên năm cuối hoặc mới tốt nghiệp Đại học chuyên ngành Luật.\n- Có thể thực tập tối thiểu 4 ngày/tuần.\n- Thái độ làm việc tích cực, chăm chỉ, cẩn thận, có trách nhiệm và tinh thần học hỏi cao.\n- Có phương tiện đi lại cá nhân và máy tính xách tay phục vụ công việc.\n\n### Quyền lợi & Chế độ đãi ngộ:\n- Được hỗ trợ đóng dấu thực tập, cung cấp số liệu viết báo cáo tốt nghiệp.\n- Hỗ trợ phụ cấp xăng xe đi lại + Thưởng hiệu quả xử lý hồ sơ thực tế.\n- Được hướng dẫn tận tình, cầm tay chỉ việc bởi các chuyên gia và Luật sư gạo cội.\n- Cơ hội được giữ lại làm nhân viên chính thức (Chuyên viên pháp lý tập sự) sau kỳ thực tập mà không cần thử việc.','\n',char(10)),NULL,NULL);
INSERT INTO recruitment VALUES(4,'Chuyên viên Quyết toán Thuế & Kế toán Doanh nghiệp','Đà Nẵng','Toàn thời gian','12 - 18 triệu VNĐ','Tư vấn và thực hiện dịch vụ báo cáo tài chính, quyết toán thuế thu nhập cá nhân, thuế thu nhập doanh nghiệp cho tệp khách hàng của công ty luật.',replace('### Chi tiết công việc:\n- Trực tiếp quản lý và thực hiện dịch vụ kế toán thuế trọn gói cho tệp khách hàng doanh nghiệp được phân công.\n- Soạn thảo và nộp tờ khai thuế GTGT, TNCN, TNDN, tình hình sử dụng hóa đơn định kỳ (tháng/quý/năm).\n- Lập báo cáo tài chính, quyết toán thuế năm và trực tiếp giải trình số liệu với cơ quan thuế khi có yêu cầu thanh tra, kiểm tra.\n- Tư vấn cho khách hàng về tối ưu hóa chi phí hợp lý, hợp lệ theo đúng quy định pháp luật thuế hiện hành.\n\n### Yêu cầu ứng viên:\n- Tốt nghiệp Đại học trở lên chuyên ngành Kế toán, Kiểm toán, Tài chính doanh nghiệp.\n- Ít nhất 02 năm kinh nghiệm thực tế làm kế toán tổng hợp hoặc kế toán thuế (ưu tiên ứng viên từng làm việc tại các đại lý thuế, công ty dịch vụ kế toán).\n- Thành thạo các phần mềm kế toán (Misa, Fast...) và phần mềm kê khai thuế HTKK.\n- Chịu khó, cẩn thận, trung thực, có năng lực giao tiếp và tư vấn khách hàng tốt.\n\n### Quyền lợi & Chế độ đãi ngộ:\n- Lương cứng cạnh tranh 12 - 18 triệu VNĐ (xem xét tăng lương hàng năm) + phụ cấp trách nhiệm + phần trăm doanh thu dịch vụ kế toán thường xuyên.\n- Môi trường làm việc độc lập, tôn trọng sáng tạo cá nhân.\n- Đầy đủ chế độ phúc lợi: Bảo hiểm xã hội, thưởng Lễ Tết lớn, nghỉ mát hàng năm.\n- Được tham gia các khóa cập nhật chính sách thuế mới nhất từ các chuyên gia Tổng cục Thuế.','\n',char(10)),NULL,NULL);
INSERT INTO recruitment VALUES(5,'Nhân viên tư vấn','Đà Nẵng','Toàn thời gian','Thỏa thuận','tư vấn','',NULL,NULL);
INSERT INTO recruitment_benefits VALUES(1,'Lương Thưởng Vượt Trội','Lương cứng cạnh tranh theo đúng năng lực thực tế. Cơ chế thưởng vụ việc, hoa hồng doanh số mang về cực kỳ vượt trội và minh bạch từ 10% - 20% doanh thu vụ việc.','Coins');
INSERT INTO recruitment_benefits VALUES(2,'Lộ Trình Thăng Tiến Rõ Ràng','Kế hoạch phát triển sự nghiệp cá nhân chi tiết. Đánh giá tăng lương và thăng cấp vị trí định kỳ 6 tháng một lần dựa hoàn toàn trên năng lực và đóng góp thực tế.','TrendingUp');
INSERT INTO recruitment_benefits VALUES(3,'Đào Tạo Thực Chiến','Cơ hội rèn luyện sâu rộng thông qua các buổi chia sẻ chuyên đề pháp luật định kỳ. Được kèm cặp, dìu dắt trực tiếp (1-on-1) bởi các Luật sư thành viên gạo cội.','BookOpen');
INSERT INTO recruitment_benefits VALUES(4,'Phúc Lợi Toàn Diện','Hưởng đầy đủ bảo hiểm xã hội, bảo hiểm y tế. Các hoạt động Teambuilding sôi nổi, du lịch nghỉ dưỡng 5 sao trong & ngoài nước ít nhất 1 lần/năm cùng gia đình Ánh Dương Law.','Heart');
INSERT INTO recruitment_process VALUES(1,'01','Gửi hồ sơ ứng tuyển','Ứng viên nộp CV trực tiếp thông qua biểu mẫu website hoặc email tuyển dụng. Bộ phận HR tiến hành sàng lọc và phản hồi kết quả trong tối đa 3 ngày làm việc.');
INSERT INTO recruitment_process VALUES(2,'02','Phỏng vấn sơ loại','Một buổi trò chuyện thân mật (trực tiếp hoặc online) cùng bộ phận HR để chia sẻ định hướng công việc, lộ trình nghề nghiệp và mức độ phù hợp văn hóa làm việc.');
INSERT INTO recruitment_process VALUES(3,'03','Đánh giá năng lực chuyên môn','Ứng viên tham gia thực hiện bài đánh giá kiến thức chuyên môn thực tế hoặc trao đổi chuyên sâu trực tiếp cùng Hội đồng Luật sư thành viên sáng lập của Ánh Dương Law.');
INSERT INTO recruitment_process VALUES(4,'04','Nhận việc & Onboarding','Bộ phận nhân sự gửi Thư mời nhận việc (Offer Letter) với các thỏa thuận đãi ngộ chi tiết. Ứng viên tham gia chương trình đào tạo hội nhập có Mentor dẫn dắt.');
INSERT INTO news VALUES(1,'Quy định mới về Luật Đất đai 2024','Những điểm mới quan trọng trong Luật Đất đai 2024 ảnh hưởng đến doanh nghiệp.',NULL,'2024-03-15','https://picsum.photos/seed/news1/800/600','Pháp luật',1,NULL,NULL);
INSERT INTO news VALUES(2,'Hướng dẫn thủ tục thành lập doanh nghiệp','Cập nhật các bước và thủ tục cần thiết để thành lập công ty năm 2024.',NULL,'2024-03-10','https://picsum.photos/seed/news2/800/600','Doanh nghiệp',1,NULL,NULL);
INSERT INTO legal_forms VALUES(1,'Đơn khởi kiện dân sự (Mẫu số 23-DS)','Dân sự','Mẫu đơn chuẩn dùng để khởi kiện các vụ án dân sự, tranh chấp hợp đồng, đất đai theo Nghị quyết 01/2017/NQ-HĐTP.',replace('CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM\nĐộc lập - Tự do - Hạnh phúc\n--------------------\n\n..., ngày ... tháng ... năm ...\n\nĐƠN KHỞI KIỆN\n\nKính gửi: Tòa án nhân dân ....................................................\n\nNgười khởi kiện: .............................................................\nĐịa chỉ cư trú: ...............................................................\nSố điện thoại: ............................ Email: ..........................\n\nNgười bị kiện: ...............................................................\nĐịa chỉ cư trú: ...............................................................\nSố điện thoại: ............................ Email: ..........................\n\nYÊU CẦU TÒA ÁN GIẢI QUYẾT NHỮNG VẤN ĐỀ SAU ĐÂY:\n1. ............................................................................\n2. ............................................................................\n\nDANH MỤC TÀI LIỆU, CHỨNG CỨ KÈM THEO ĐƠN:\n1. Bản sao Căn cước công dân.\n2. Tài liệu chứng minh quyền sở hữu tài sản / Hợp đồng tranh chấp.\n3. ............................................................................\n\nNgười khởi kiện (Ký và ghi rõ họ tên)','\n',char(10)),1);
INSERT INTO legal_forms VALUES(2,'Đơn xin ly hôn thuận tình','Hôn nhân','Mẫu đơn dùng khi cả hai vợ chồng tự nguyện ly hôn và đã thỏa thuận xong các vấn đề về tài sản, con chung.',replace('CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM\nĐộc lập - Tự do - Hạnh phúc\n--------------------\n\nĐƠN YÊU CẦU CÔNG NHẬN THUẬN TÌNH LY HÔN,\nNUÔI CON VÀ CHIA TÀI SẢN KHI LY HÔN\n\nKính gửi: Tòa án nhân dân ....................................................\n\nChúng tôi gồm:\nChồng: ........................................... Sinh năm: .................\nCăn cước công dân số: ............................ Cấp ngày: ................\nĐịa chỉ thường trú: ...........................................................\n\nVợ: ............................................. Sinh năm: .................\nCăn cước công dân số: ............................ Cấp ngày: ................\nĐịa chỉ thường trú: ...........................................................\n\nChúng tôi làm đơn này đề nghị Tòa án công nhận thuận tình ly hôn với các nội dung sau:\n1. Về quan hệ hôn nhân: ........................................................\n2. Về con chung: ...............................................................\n3. Về tài sản chung và nợ chung: ................................................\n\nKính đề nghị Tòa án giải quyết.\n\nCHỒNG KÝ TÊN                                 VỢ KÝ TÊN','\n',char(10)),1);
INSERT INTO legal_forms VALUES(3,'Đơn khởi kiện vụ án hành chính','Hành chính','Dùng để khởi kiện quyết định hành chính, hành vi hành chính trái pháp luật của cơ quan nhà nước.',replace('CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM\nĐộc lập - Tự do - Hạnh phúc\n--------------------\n\nĐƠN KHỞI KIỆN HÀNH CHÍNH\n\nKính gửi: Tòa án nhân dân ....................................................\n\nNgười khởi kiện: .............................................................\nĐịa chỉ: ......................................................................\n\nĐối tượng bị khởi kiện: Quyết định hành chính số: ....... ngày .... của .............\nVề việc: ......................................................................\n\nNội dung khởi kiện và lý do: ...................................................\n...............................................................................\n\nYêu cầu Tòa án giải quyết:\n- Hủy bỏ toàn bộ/một phần Quyết định hành chính nêu trên.\n\nNgười khởi kiện','\n',char(10)),1);
INSERT INTO legal_forms VALUES(4,'Mẫu giấy ủy quyền cá nhân','Hợp đồng','Mẫu giấy ủy quyền đơn giản dùng trong giao dịch dân sự, nộp và nhận hồ sơ, đại diện làm thủ tục.',replace('CỘNG HÒA XÃ HỘI CHỦ NGHĨA VIỆT NAM\nĐộc lập - Tự do - Hạnh phúc\n--------------------\n\nGIẤY ỦY QUYỀN\n\nBÊN ỦY QUYỀN (BÊN A):\nHọ và tên: ....................................... Sinh năm: .................\nCCCD số: ......................................... Địa chỉ: ..................\n\nBÊN ĐƯỢC ỦY QUYỀN (BÊN B):\nHọ và tên: ....................................... Sinh năm: .................\nCCCD số: ......................................... Địa chỉ: ..................\n\nNỘI DUNG ỦY QUYỀN:\nBên A ủy quyền cho Bên B thay mặt Bên A thực hiện các công việc sau:\n1. Nộp và nhận hồ sơ tại ......................................................\n2. Ký các giấy tờ liên quan hành chính.\n\nThời hạn ủy quyền: Từ ngày .../.../... đến ngày .../.../...\n\nBÊN ỦY QUYỀN                                 BÊN ĐƯỢC ỦY QUYỀN','\n',char(10)),1);
INSERT INTO judgments VALUES(1,'89/2023/DS-ST','Bản án sơ thẩm về Tranh chấp Hợp đồng đặt cọc mua bán bất động sản','Tòa án nhân dân Quận 1, TP. Hồ Chí Minh','14/05/2023','Dân sự','Quyết định buộc bên nhận đặt cọc hoàn trả gấp đôi số tiền cọc do vi phạm thời hạn công chứng chuyển nhượng quyền sử dụng đất thuộc lỗi của bên bán.',replace('BẢN ÁN SỐ: 89/2023/DS-ST\nVỀ VIỆC TRANH CHẤP HỢP ĐỒNG ĐẶT CỌC CHUYỂN NHƯỢNG ĐẤT\n\nVào ngày 14 tháng 5 năm 2023, tại trụ sở Tòa án nhân dân Quận 1 xét xử sơ thẩm công khai vụ án thụ lý số 120/2023/TLST-DS.\n- Nguyên đơn: Ông Nguyễn Văn A.\n- Bị đơn: Bà Trần Thị B.\n\nNHẬN ĐỊNH CỦA TÒA ÁN:\nXét hợp đồng đặt cọc ký ngày 12/01/2023 giữa nguyên đơn và bị đơn trị giá cọc 500.000.000đ. Bên bán cam kết đến ngày 12/02/2023 hoàn tất giấy tờ để công chứng. Đến hạn bên bán không thực hiện được do đất đang bị thế chấp ngân hàng chưa giải chấp. Lỗi hoàn toàn thuộc về bị đơn.\n\nQUYẾT ĐỊNH:\n1. Chấp nhận yêu cầu khởi kiện của nguyên đơn. Tuyên bố hủy hợp đồng đặt cọc.\n2. Buộc bà Trần Thị B trả lại cho ông Nguyễn Văn A số tiền đặt cọc 500.000.000đ và phạt cọc số tiền 500.000.000đ. Tổng cộng 1.000.000.000đ (Một tỷ đồng).','\n',char(10)),1);
INSERT INTO judgments VALUES(2,'42/2023/KDTM-ST','Bản án tranh chấp hợp đồng mua bán hàng hóa, phạt vi phạm và nợ gốc','Tòa án nhân dân Quận Cầu Giấy, TP. Hà Nội','28/08/2023','Kinh doanh','Buộc Công ty bê tông X thanh toán nợ gốc cho Công ty thép Y kèm lãi chậm trả và phạt vi phạm hợp đồng tối đa 8% giá trị phần nghĩa vụ bị vi phạm.',replace('BẢN ÁN SỐ: 42/2023/KDTM-ST\nVỀ TRANH CHẤP HỢP ĐỒNG MUA BÁN THÉP XÂY DỰNG\n\nTòa án nhân dân Quận Cầu Giấy xét xử sơ thẩm vụ án kinh tế thương mại nợ tiền hàng.\n- Nguyên đơn: Công ty Cổ phần Thép Y.\n- Bị đơn: Công ty TNHH Bê tông X.\n\nNHẬN ĐỊNH CỦA TÒA ÁN:\nBị đơn thừa nhận nhận đủ thép theo các hóa đơn bàn giao nhưng chưa thanh toán số tiền nợ gốc 2.450.000.000đ quá hạn 180 ngày. Điều khoản hợp đồng quy định phạt chậm trả 0.05%/ngày và phạt vi phạm 8%.\n\nQUYẾT ĐỊNH:\nBuộc Công ty TNHH Bê tông X thanh toán nợ gốc 2.450.000.000đ, tiền phạt vi phạm chậm trả 196.000.000đ (đúng 8% mức trần luật định) cho Công ty Cổ phần Thép Y.','\n',char(10)),1);
INSERT INTO judgments VALUES(3,'15/2023/LĐ-ST','Bản án sơ thẩm về Đơn phương chấm dứt hợp đồng lao động trái luật','Tòa án nhân dân TP. Thuận An, Tỉnh Bình Dương','02/11/2023','Lao động','Tuyên bố quyết định sa thải của Công ty May mặc Z là trái pháp luật, buộc nhận lại người lao động làm việc và bồi thường 6 tháng tiền lương.',replace('BẢN ÁN SỐ: 15/2023/LĐ-ST\nTRANH CHẤP ĐƠN PHƯƠNG CHẤM DỨT HỢP ĐỒNG LAO ĐỘNG\n\nXét xử vụ án sa thải kỷ luật lao động trái luật.\n- Nguyên đơn: Chị Lê Thị C.\n- Bị đơn: Công ty May mặc Z.\n\nNHẬN ĐỊNH CỦA TÒA ÁN:\nCông ty May mặc Z sa thải chị Lê Thị C với lý do tự ý nghỉ việc 5 ngày cộng dồn nhưng không mở cuộc họp kỷ luật lao động có sự tham gia của Công đoàn cơ sở, vi phạm quy trình Bộ luật Lao động 2019.\n\nQUYẾT ĐỊNH:\n1. Tuyên bố Quyết định sa thải số 45/QĐ-May mặc Z là vô hiệu.\n2. Buộc Công ty May mặc Z nhận chị C trở lại làm việc.\n3. Buộc bồi thường tiền lương trong những ngày không được làm việc và 2 tháng lương vi phạm thời hạn báo trước, tổng cộng bồi thường 72.000.000đ.','\n',char(10)),1);
INSERT INTO precedents VALUES(1,'Án lệ số 01/2016/AL','Án lệ về vụ án giết người có tính chất côn đồ','06/04/2016','Quy định hướng dẫn cụ thể về tình tiết định khung giết người có tính chất côn đồ khi bị cáo có hành vi hung hãn, coi thường mạng sống chỉ vì mâu thuẫn nhỏ nhặt.','Xác định tình tiết tăng nặng "Có tính chất côn đồ" trong tội giết người.','Hành vi vô cớ đâm chém nạn nhân do mâu thuẫn bộc phát nhỏ nhặt được áp dụng tình tiết định khung côn đồ.',1);
INSERT INTO precedents VALUES(2,'Án lệ số 02/2016/AL','Án lệ về tranh chấp tài sản là quyền sử dụng đất có người Việt kiều đóng góp','06/04/2016','Xác định công sức đóng góp của người Việt Nam định cư ở nước ngoài gửi tiền về nhờ người thân trong nước đứng tên mua hộ bất động sản khi phân chia di sản tranh chấp.','Người Việt kiều gửi tiền mua đất nhờ người trong nước đứng tên hộ.','Tòa án phải xác định công sức đóng góp của Việt kiều tương ứng tỷ lệ tiền gửi về, phân chia công bằng thay vì bác bỏ hoàn toàn.',1);
INSERT INTO precedents VALUES(3,'Án lệ số 04/2016/AL','Án lệ về tranh chấp hợp đồng chuyển nhượng quyền sử dụng đất','06/04/2016','Trường hợp hợp đồng chuyển nhượng đất bằng giấy viết tay trước ngày Luật Đất đai có hiệu lực nhưng các bên đã giao tiền và nhận đất canh tác ổn định lâu dài.','Hiệu lực của hợp đồng viết tay chưa công chứng nhưng đã thực hiện nghĩa vụ giao tiền, đất.','Công nhận hiệu lực hợp đồng chuyển nhượng thực tế nhằm bảo đảm tính ổn định của giao dịch dân sự và đời sống người dân.',1);
INSERT INTO testimonials VALUES(1,'Chị Zema','Nhà đầu tư bất động sản',5,'Ánh Dương Law đã đồng hành cùng tôi trong thương vụ mua bán sáp nhập dự án nghỉ dưỡng tại Đà Nẵng. Sự am hiểu quy hoạch địa phương và tốc độ giải quyết hồ sơ của đội ngũ thực sự vượt ngoài mong đợi!','https://picsum.photos/seed/user1/100/100','Zema Group',1);
INSERT INTO testimonials VALUES(2,'Ông Lê Hoàng Nam','Giám đốc Công ty TechVina',5,'Chúng tôi sử dụng dịch vụ Tư vấn thường xuyên của Ánh Dương Law hơn 3 năm qua. Các Luật sư luôn túc trực, phản hồi rủi ro hợp đồng siêu tốc và bảo vệ tối đa lợi thế thương mại cho chúng tôi.','https://picsum.photos/seed/user2/100/100','TechVina Corp',1);
INSERT INTO testimonials VALUES(3,'Bà Trần Mỹ Linh','Trưởng phòng Nhân sự',5,'Rất hài lòng với giải pháp tái cấu trúc lao động mà Ánh Dương Law tư vấn. Quy trình hòa giải và xây dựng thỏa ước lao động tập thể cực kỳ khéo léo, không để xảy ra bất kỳ tranh chấp hay căng thẳng nội bộ nào.','https://picsum.photos/seed/user3/100/100','Tập đoàn H&K',1);
