INSERT INTO record_types VALUES(1,'DS','Dân sự','Tranh chấp dân sự, thừa kế, hợp đồng dân sự, bồi thường thiệt hại ngoài hợp đồng...','bg-orange-500',1);
INSERT INTO record_types VALUES(2,'HS','Hình sự','Các vụ án hình sự, bào chữa, bảo vệ quyền lợi hợp pháp của bị can, bị cáo, đương sự...','bg-rose-500',1);
INSERT INTO record_types VALUES(3,'HC','Hành chính','Khiếu nại, khởi kiện quyết định hành chính, hành vi hành chính của cơ quan nhà nước...','bg-blue-500',1);
INSERT INTO record_types VALUES(4,'HNGĐ','Hôn nhân & Gia đình','Thủ tục ly hôn, tranh chấp quyền nuôi con, chia tài sản chung, cấp dưỡng...','bg-pink-500',1);
INSERT INTO record_types VALUES(5,'KDTM','Kinh doanh & Thương mại','Tranh chấp hợp đồng thương mại, mua bán hàng hóa, tranh chấp nội bộ công ty, cổ đông...','bg-purple-500',1);
INSERT INTO record_types VALUES(6,'LĐ','Lao động','Tranh chấp hợp đồng lao động, sa thải, tiền lương, bảo hiểm xã hội, kỷ luật lao động...','bg-emerald-500',1);
INSERT INTO record_types VALUES(7,'ĐĐ','Đất đai & Bất động sản','Tranh chấp quyền sử dụng đất, cấp sổ đỏ, thu hồi đất, bồi thường tái định cư, giao dịch nhà đất...','bg-amber-500',1);
INSERT INTO record_types VALUES(8,'DN','Doanh nghiệp & Đầu tư','Tư vấn thành lập, sáp nhập, giải thể doanh nghiệp, xin giấy phép con, dự án đầu tư...','bg-indigo-500',1);
INSERT INTO record_types VALUES(9,'TV','Tư vấn pháp luật','Cung cấp dịch vụ tư vấn pháp lý thường xuyên, soạn thảo hợp đồng, di chúc, rà soát văn bản...','bg-blue-500',1);
INSERT INTO record_types VALUES(10,'K','Khác','Các dịch vụ pháp lý và vụ việc khác không thuộc các phân loại trên...','bg-gray-500',1);
