INSERT INTO ai_agent_memories VALUES(1,'system','user_preference','legal_preference','Quy chuẩn Định dạng Văn bản Tố tụng','Các văn bản tố tụng (Đơn khởi kiện, Bản tự khai, Đơn đề nghị) gửi Tòa án luôn phải tuân thủ chuẩn phông chữ Times New Roman 14, dãn dòng 1.25, có đầy đủ căn cứ viện dẫn Bộ luật Tố tụng Dân sự 2015 và thông tin người đại diện theo ủy quyền.','Quy chuẩn soạn thảo văn bản tố tụng: font Times New Roman 14, căn cứ BLTTDS 2015.','SYSTEM',NULL,0.94999999999999995559,0.97999999999999998223,1,'2026-09-07T07:35:38.996Z','active',NULL,'["tố_tụng","văn_bản","quy_chuẩn","định_dạng"]','{}','2026-09-07T07:35:38.996Z','2026-09-07T07:35:38.996Z');
INSERT INTO ai_agent_memories VALUES(2,'system','decision_pattern','case_note','Chiến lược Xử lý Vụ án Tranh chấp Đất đai','Khi tiếp nhận tranh chấp ranh giới đất đai hoặc thừa kế quyền sử dụng đất, bước đầu tiên bắt buộc phải kiểm tra thủ tục Hòa giải tại UBND cấp xã/phường theo Điều 202 Luật Đất đai trước khi nộp đơn khởi kiện tại TAND cấp quận/huyện.','Tranh chấp đất đai bắt buộc hòa giải cấp xã trước khi khởi kiện.','LAW',NULL,0.92000000000000003996,0.94999999999999995559,1,'2026-09-07T07:35:38.996Z','active',NULL,'["đất_đai","hòa_giải","khởi_kiện","thủ_tục"]','{}','2026-09-07T07:35:38.996Z','2026-09-07T07:35:38.996Z');
INSERT INTO ai_agent_memories VALUES(3,'system','client_fact','client_profile','Hồ sơ Khách hàng Tập đoàn Bất động sản Đô Thành','Khách hàng ưu tiên trao đổi trực tiếp qua Ban Pháp chế, yêu cầu báo cáo tiến độ bằng văn bản tóm tắt vào thứ Sáu hàng tuần trước 15:00. Người liên hệ chính: Ông Trần Đình Toàn (Trưởng phòng Pháp chế).','Tập đoàn Đô Thành yêu cầu báo cáo tiến độ thứ 6 hàng tuần qua Trưởng phòng Pháp chế.','CLIENT','KH-DOTHANH',0.88000000000000000444,0.9000000000000000222,1,'2026-09-07T07:35:38.996Z','active',NULL,'["khách_hàng_vip","đô_thành","báo_cáo_tuần"]','{}','2026-09-07T07:35:38.996Z','2026-09-07T07:35:38.996Z');
INSERT INTO ai_agent_memories VALUES(4,'system','case_insight','case_note','Kinh nghiệm Vụ án Hợp đồng Xây dựng EPC','Đối với tranh chấp hợp đồng EPC xây dựng công trình, cần đặc biệt lưu ý kiểm tra Nhật ký thi công, Biên bản nghiệm thu từng giai đoạn và Chứng từ xác nhận khối lượng phát sinh ngoài phạm vi hợp đồng ban đầu.','Tranh chấp EPC cần đối chiếu kỹ Nhật ký công trình và nghiệm thu khối lượng phát sinh.','CASE',NULL,0.84999999999999997779,0.92000000000000003996,1,'2026-09-07T07:35:38.996Z','active',NULL,'["hợp_đồng_epc","xây_dựng","chứng_cứ","nghiệm_thu"]','{}','2026-09-07T07:35:38.996Z','2026-09-07T07:35:38.996Z');
INSERT INTO ai_agent_memories VALUES(5,'system','user_preference','procedural_habit','Nguyên tắc Bảo mật Hồ sơ Khách hàng','Tuyệt đối không gửi bản sao Giấy chứng nhận quyền sử dụng đất hoặc CMND/CCCD của thân chủ qua các kênh chưa được mã hóa mà không có sự phê duyệt của Luật sư điều hành.','Bảo mật tài liệu nhạy cảm của khách hàng, cấm gửi qua kênh không an toàn.','SYSTEM',NULL,0.97999999999999998223,1.0,1,'2026-09-07T07:35:38.996Z','active',NULL,'["bảo_mật","quy_chế","cccd","sổ_đỏ"]','{}','2026-09-07T07:35:38.996Z','2026-09-07T07:35:38.996Z');
