INSERT INTO ai_training_data VALUES(1,'Quy trình tiếp nhận khách hàng mới','quy trình tiếp nhận khách hàng',replace('Bước 1: Tiếp nhận thông tin từ tổng đài hoặc livechat.\nBước 2: Phân nhóm dịch vụ (Hình sự, Dân sự, Doanh nghiệp...).\nBước 3: Người điều phối ERP phân công Luật sư phụ trách chính.\nBước 4: Luật sư chủ động liên hệ đặt lịch tư vấn trực tiếp trong vòng 2 giờ.','\n',char(10)),'2026-09-07T07:35:39.018Z');
INSERT INTO ai_training_data VALUES(2,'Bảo mật thông tin khách hàng','bảo mật thông tin khách hàng hoặc hồ sơ vụ việc','Tất cả thông tin hồ sơ của khách hàng tại Ánh Dương Law được bảo mật tuyệt đối theo Luật Luật sư 2006. Nhân viên không được tự ý tiết lộ chi tiết vụ án hoặc danh tính khách hàng cho bên thứ ba khi chưa có sự đồng ý bằng văn bản của Giám đốc hoặc chính khách hàng.','2026-09-07T07:35:39.018Z');
INSERT INTO ai_training_data VALUES(3,'Quy chế báo cáo công việc','quy chế báo cáo công việc hoặc ghi nhận log','Mỗi luật sư và chuyên viên tại Ánh Dương Law có trách nhiệm cập nhật tiến độ công việc (ERP Records) và ghi lại nhật ký tác vụ hàng ngày trước 17:30. Các trường hợp hoàn thành xuất sắc nhiệm vụ sẽ được xem xét thưởng KPI cuối tháng.','2026-09-07T07:35:39.018Z');
